const app = new Hono()

const KINDS = new Set(['quote', 'sample', 'contact'])

const clean = (v: unknown, max = 500): string | undefined =>
  typeof v === 'string' && v.trim() ? v.trim().slice(0, max) : undefined

/**
 * Short, human-quotable reference. Collisions are retried, not trusted.
 *
 * Characters come from a CSPRNG rather than `Math.random()`: a reference is the
 * only thing protecting an artwork file from being guessed, and 25 symbols in a
 * predictable sequence is not a secret. Values above the largest multiple of the
 * alphabet length are rejected so the draw is unbiased.
 */
function makeReference(prefix = 'KL'): string {
  const alphabet = 'ACDEFGHJKLMNPQRTUVWXY34679'
  const limit = 256 - (256 % alphabet.length)
  let out = ''
  while (out.length < 5) {
    for (const byte of randomBytes(5)) {
      if (byte >= limit) continue
      out += alphabet[byte % alphabet.length]
      if (out.length === 5) break
    }
  }
  return `${prefix}-${out}`
}

/**
 * Market configuration for the browser.
 *
 * Deliberately public and deliberately thin: countries, currencies, the
 * owner's commercial policy and the current rates. No customer data, no
 * provider credentials, and no price list — the price list does not exist yet.
 */
app.get('/market', async (c) => {
  try {
    const [policy, rates, destinations, products] = await Promise.all([
      loadPolicy(),
      listRates(),
      listDestinations(),
      listProductRules(),
    ])
    const snapshot = toSnapshot(policy, rates, destinations, products)
    return c.json({
      ...snapshot,
      countries: COUNTRIES,
      currencies: CURRENCY_CODES.map((code) => CURRENCIES[code]),
      postal: Object.fromEntries(
        COUNTRIES.map((country) => {
          const rule = postalRule(country.code)
          return [country.code, { label: rule.label, hint: rule.hint, required: rule.required }]
        }),
      ),
    })
  } catch (error) {
    console.error('[market] snapshot failed', error)
    const fallback = toSnapshot(mergePolicy(null), [], [], [])
    return c.json({
      ...fallback,
      countries: COUNTRIES,
      currencies: CURRENCY_CODES.map((code) => CURRENCIES[code]),
      postal: Object.fromEntries(
        COUNTRIES.map((country) => {
          const rule = postalRule(country.code)
          return [country.code, { label: rule.label, hint: rule.hint, required: rule.required }]
        }),
      ),
    })
  }
})

/**
 * A suggestion, never an answer. Header-based only: no IP is stored and no
 * third-party geolocation is called. The browser keeps the visitor's choice.
 */
app.get('/market/geo', (c) => {
  const geo = geoFromHeaders(new Headers(c.req.raw.headers))
  if (!geo.country) {
    return c.json({ country: null, currency: null, source: 'none' }, 200)
  }
  const country = COUNTRY_BY_CODE[geo.country]
  return c.json({
    country: geo.country,
    name: country?.name ?? geo.country,
    localCurrency: country?.currency ?? null,
    currency: geo.currency,
    source: geo.source,
    note: 'Suggested from your connection. Change it at any time — the choice is stored in this browser.',
  })
})

/** Server-side conversion, so a converted figure is never computed from a client claim. */
app.post('/market/convert', async (c) => {
  let body: Record<string, unknown> = {}
  try {
    body = (await c.req.json()) as Record<string, unknown>
  } catch {
    return c.json({ error: 'Send JSON.' }, 400)
  }
  const amount = Number(body.amount)
  const to = String(body.currency ?? '').toUpperCase()
  if (!isCurrencyCode(to)) return c.json({ error: `Unsupported currency: ${body.currency ?? '(none)'}` }, 400)
  const policy = await loadPolicy()
  const rates = await listRates()
  const result = convert(amount, to, pickRate(rates, to, policy), policy.fx)
  if (!result.ok) {
    return c.json({ error: result.message, reason: result.reason }, result.reason === 'no-rate' ? 412 : 400)
  }
  return c.json({ ok: true, price: result.price })
})

/**
 * The single entry point every form on the site posts to.
 *
 * Validation lives in src/generated/lead.hooks.ts as well, but this route adds
 * what a public form actually needs: a honeypot, duplicate suppression for
 * double-submits, and a reference the customer can quote back.
 */
app.post('/enquiries', async (c) => {
  let body: Record<string, unknown>
  try {
    body = (await c.req.json()) as Record<string, unknown>
  } catch {
    return c.json({ error: 'Could not read that submission.' }, 400)
  }

  // Honeypot: a real person never fills a hidden field.
  if (typeof body.website === 'string' && body.website.trim() !== '') {
    return c.json({ ok: true, reference: null, note: 'accepted' }, 201)
  }

  const kind = String(body.kind ?? '').trim()
  if (!KINDS.has(kind)) {
    return c.json({ error: 'Unknown enquiry type.' }, 400)
  }

  const name = String(body.name ?? '').trim()
  const email = String(body.email ?? '').trim().toLowerCase()
  const message = String(body.message ?? '').trim()

  // ── Destination ────────────────────────────────────────────────────────────
  // The country decides the currency, the postal format and whether we may
  // accept the enquiry at all, so it is resolved before anything else.
  const policy = await loadPolicy()
  const rawCountry = String(body.country ?? '').trim().toUpperCase()
  const country = isCountryCode(rawCountry) ? rawCountry : ''
  if (rawCountry && !country) {
    return c.json({ error: `${rawCountry} is not a destination we recognise.`, fields: { country: 'Choose a country from the list.' } }, 400)
  }
  // Older form versions did not send a country; they were India-only by
  // construction, so that is what they are recorded as.
  const destinationCountry = country || 'IN'
  const countryRecord = COUNTRY_BY_CODE[destinationCountry]

  const destinations = await listDestinations()
  const destination = resolveDestination(destinationCountry, destinations, policy)
  if (destination.status === 'not-served') {
    return c.json(
      {
        error: `We do not deliver to ${destination.name}. Nothing was submitted — write to us if you are arranging your own freight.`,
        code: 'destination_not_served',
        country: destination.code,
      },
      409,
    )
  }

  // ── Postal code ────────────────────────────────────────────────────────────
  // A postal code's format is country-specific. The six-digit Indian PIN check
  // that used to live here rejected every international enquiry.
  const rawPostal = String(body.postalCode ?? body.pincode ?? '').trim()
  const postal = validatePostal(destinationCountry, rawPostal)
  if (!postal.ok) {
    const label = postalRule(destinationCountry).label
    return c.json(
      {
        error: `${label}: ${postal.message}`,
        fields: { postalCode: postal.message, ...(destinationCountry === 'IN' ? { pincode: postal.message } : {}) },
      },
      400,
    )
  }
  const postalCode = postal.value
  // `pincode` remains the India-specific column the inbox has always shown.
  const pincode = destinationCountry === 'IN' ? postalCode : null

  // ── Currency ──────────────────────────────────────────────────────────────
  const requested = String(body.currency ?? '').trim().toUpperCase()
  if (requested && !isCurrencyCode(requested)) {
    return c.json({ error: `${requested} is not a currency we quote in.`, fields: { currency: 'Choose a supported currency.' } }, 400)
  }
  const resolved = resolveCurrency(destinationCountry, policy.fx.fallbackCurrency)
  const currency = isCurrencyCode(requested) ? requested : resolved.currency
  if (!policy.quoteCurrencies.includes(currency)) {
    return c.json(
      {
        error: `We do not issue quotations in ${currency}. Supported: ${policy.quoteCurrencies.join(', ')}.`,
        fields: { currency: `Quotes are available in ${policy.quoteCurrencies.join(', ')}.` },
      },
      400,
    )
  }

  if (name.length < 2) return c.json({ error: 'Please give a name.' }, 400)
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) {
    return c.json({ error: 'That email address does not look valid.' }, 400)
  }
  if (kind === 'contact' && message.length < 10) {
    return c.json({ error: 'Please add a little more detail — at least a sentence.' }, 400)
  }
  if (kind === 'quote' && !body.productSlug && !body.structureId && message.length < 10) {
    return c.json(
      { error: 'A quote request needs a format, a structure, or a description of what you need.' },
      400,
    )
  }

  const productSlug = clean(body.productSlug, 120) ?? null

  // Product × destination capability. Unconfigured means "we will answer",
  // not "we can make it" — only an explicit rule can refuse.
  if (productSlug) {
    const productRules = await listProductRules()
    const rule = resolveProductRule(productRules, productSlug, destinationCountry)
    if (!rule.available) {
      return c.json(
        {
          error: `That format is not offered for delivery to ${destination.name}. Nothing was submitted — ask us and we will suggest an alternative.`,
          code: 'product_unavailable',
          country: destinationCountry,
          productSlug,
        },
        409,
      )
    }
  }

  // A double-clicked submit, or a retry after a slow response, must not create
  // a second row for the same enquiry.
  const recent = await prisma.lead.findFirst({
    where: {
      email,
      kind,
      productSlug,
      createdAt: { gte: new Date(Date.now() - 10 * 60 * 1000) },
    },
    orderBy: { createdAt: 'desc' },
  })
  if (recent) {
    return c.json({ ok: true, reference: recent.reference, duplicate: true }, 200)
  }

  let reference = makeReference()
  for (let attempt = 0; attempt < 5; attempt++) {
    const clash = await prisma.lead.findFirst({ where: { reference } })
    if (!clash) break
    reference = makeReference()
  }

  const payload =
    body.payload && typeof body.payload === 'object'
      ? JSON.stringify(body.payload).slice(0, 4000)
      : clean(body.payload, 4000)

  // If the visitor was shown an indicative figure, snapshot the exact numbers
  // they saw. The conversion is redone here from the stored rate — a client-
  // supplied converted amount is never trusted.
  const indicative =
    body.indicative && typeof body.indicative === 'object'
      ? (body.indicative as Record<string, unknown>)
      : null
  const baseAmount = Number(indicative?.baseAmount)
  let fxSnapshot: {
    baseCurrency: string
    baseAmount: number
    fxRate: number | null
    displayAmount: number | null
    fxFetchedAt: Date | null
  } | null = null
  if (Number.isFinite(baseAmount) && baseAmount >= 0) {
    const rates = await listRates()
    const conversion = convert(baseAmount, currency, pickRate(rates, currency, policy), policy.fx)
    fxSnapshot = {
      baseCurrency: policy.fx.baseCurrency,
      baseAmount,
      fxRate: conversion.ok ? conversion.price.effectiveRate : null,
      displayAmount: conversion.ok ? conversion.price.displayAmount : null,
      fxFetchedAt: conversion.ok ? new Date(conversion.price.fetchedAt) : null,
    }
  }

  try {
    const created = await prisma.lead.create({
      data: {
        reference,
        kind,
        status: 'new',
        name: name.slice(0, 120),
        email,
        company: clean(body.company, 160),
        phone: clean(body.phone, 40),
        city: clean(body.city, 120),
        destination: clean(body.destination, 120),
        pincode,
        country: destinationCountry,
        countryName: countryRecord?.name ?? destinationCountry,
        postalCode: postalCode || null,
        currency,
        baseCurrency: fxSnapshot?.baseCurrency ?? null,
        baseAmount: fxSnapshot?.baseAmount ?? null,
        fxRate: fxSnapshot?.fxRate ?? null,
        displayAmount: fxSnapshot?.displayAmount ?? null,
        fxFetchedAt: fxSnapshot?.fxFetchedAt ?? null,
        productSlug,
        structureId: clean(body.structureId, 60),
        quantity: clean(body.quantity, 60),
        dimensions: clean(body.dimensions, 120),
        board: clean(body.board, 80),
        finishing: clean(body.finishing, 200),
        foil: clean(body.foil, 120),
        printing: clean(body.printing, 120),
        deliveryRequirements: clean(body.deliveryRequirements, 800),
        message: message ? message.slice(0, 6000) : null,
        payload,
        source: clean(body.source, 300),
      },
    })

    // If the enquiry quotes an artwork reference, attach the file record to the
    // lead so the desk sees the exact version that was checked.
    const artworkRef = clean(body.artworkRef, 40)
    if (artworkRef) {
      await prisma.artwork
        .updateMany({ where: { reference: artworkRef }, data: { leadId: created.id } })
        .catch(() => undefined)
    }

    return c.json({ ok: true, reference: created.reference, id: created.id }, 201)
  } catch (error) {
    console.error('[enquiries] create failed', error)
    return c.json({ error: 'We could not save that. Please email us directly instead.' }, 500)
  }
})

