/**
 * Sitemap built from the same catalogue the UI renders, so it cannot drift.
 * URLs use the request's own origin: the production domain is still a
 * placeholder in src/lib/site.ts, and a hard-coded guess would be worse than
 * deriving the host that actually served the request.
 */
app.get('/sitemap.xml', (c) => {
  const origin = new URL(c.req.url).origin
  const paths = new Set<string>([...STATIC_ROUTES, ...POLICY_SLUGS.map((s) => `/${s}`)])

  for (const family of FAMILIES) {
    paths.add(`/packaging/${family.slug}`)
    for (const product of PRODUCTS.filter((p) => p.family === family.id)) {
      paths.add(`/packaging/${family.slug}/${product.slug}`)
    }
  }
  for (const industry of INDUSTRIES) paths.add(`/industries/${industry.slug}`)
  for (const resource of RESOURCES) paths.add(`/resources/${resource.slug}`)

  const today = new Date().toISOString().slice(0, 10)
  const body = `<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
${[...paths]
  .map(
    (p) =>
      `  <url><loc>${origin}${p}</loc><lastmod>${today}</lastmod>${
        p === '/studio' || p === '/quote' ? '<priority>0.9</priority>' : ''
      }</url>`,
  )
  .join('\n')}
</urlset>
`
  return c.body(body, 200, { 'content-type': 'application/xml; charset=utf-8' })
})

/* ------------------------------ artwork ------------------------------ */

const MAX_ARTWORK_BYTES = 25 * 1024 * 1024

/**
 * Uploads are unauthenticated by design — the visitor has not signed in yet —
 * so the route is throttled per client address. Each request may hold 25 MB on
 * disk, and without a ceiling a script could fill the volume.
 *
 * The key is the first `x-forwarded-for` hop. That is only trustworthy if the
 * edge strips an inbound value; if this is ever run without a trusted proxy in
 * front, move the limit to the proxy rather than trusting the header here.
 */
const UPLOADS_PER_HOUR = 20
const artworkUploads = new Map<string, number[]>()

function uploadThrottled(c: { req: { header: (n: string) => string | undefined } }): number {
  const ip = c.req.header('x-forwarded-for')?.split(',')[0]?.trim() || 'local'
  const now = Date.now()
  const recent = (artworkUploads.get(ip) ?? []).filter((t) => now - t < 60 * 60 * 1000)
  if (recent.length >= UPLOADS_PER_HOUR) {
    artworkUploads.set(ip, recent)
    return Math.ceil((60 * 60 * 1000 - (now - recent[0])) / 60000)
  }
  recent.push(now)
  artworkUploads.set(ip, recent)
  return 0
}

/**
 * Upload + prepress check in one request.
 *
 * The check runs again on the server even though the browser already ran it:
 * the browser result is convenience, the server result is the record. A client
 * that lies about its own verdict must not produce a "ready for press" row.
 */
app.post('/artwork', async (c) => {
  const retryIn = uploadThrottled(c)
  if (retryIn > 0) {
    return c.json(
      { error: `Too many uploads from this connection. Try again in about ${retryIn} minutes, or send a link to the file instead.` },
      429,
    )
  }

  let form: Record<string, unknown>
  try {
    form = (await c.req.parseBody()) as Record<string, unknown>
  } catch {
    return c.json({ error: 'Could not read that upload.' }, 400)
  }

  const file = form.file
  if (!(file instanceof File)) {
    return c.json({ error: 'Attach a file to check.' }, 400)
  }
  if (file.size === 0) {
    return c.json({ error: 'That file is empty.' }, 400)
  }
  if (file.size > MAX_ARTWORK_BYTES) {
    return c.json(
      { error: `Files above ${MAX_ARTWORK_BYTES / 1024 / 1024} MB cannot be checked here. Send a link instead.` },
      413,
    )
  }

  const bytes = new Uint8Array(await file.arrayBuffer())
  const meta = inspectArtwork(bytes)

  const num = (v: unknown): number | undefined => {
    const n = Number(v)
    return Number.isFinite(n) && n > 0 ? n : undefined
  }

  const widthMm = num(form.panelWidthMm)
  const heightMm = num(form.panelHeightMm)
  if (!widthMm || !heightMm) {
    return c.json({ error: 'The panel size is required so resolution can be judged at final size.' }, 400)
  }

  const report = evaluateArtwork(meta, {
    widthMm,
    heightMm,
    bleedMm: num(form.bleedMm) ?? 3,
    minDpi: num(form.minDpi),
    label: clean(form.panelLabel, 60) ?? 'this panel',
  })

  const reference = makeReference('AW')
  // Artwork references are retried against the table too: `GET /artwork/:ref/file`
  // resolves by reference, so a duplicate would eventually serve someone else's file.
  let artworkReference = reference
  for (let attempt = 0; attempt < 5; attempt++) {
    const clash = await prisma.artwork.findFirst({ where: { reference: artworkReference } })
    if (!clash) break
    artworkReference = makeReference('AW')
  }
  const storedAs = `${artworkReference}-${Date.now()}`
  const dir = path.join(process.cwd(), '.data', 'artwork')
  try {
    await mkdir(dir, { recursive: true })
    await writeFile(path.join(dir, storedAs), bytes)
  } catch (error) {
    console.error('[artwork] could not store file', error)
    return c.json({ error: 'The file could not be stored. Please try again.' }, 500)
  }

  const summary = summarise(report)
  try {
    await prisma.artwork.create({
      data: {
        reference: artworkReference,
        filename: file.name.slice(0, 200) || 'artwork',
        mime: file.type || 'application/octet-stream',
        bytes: file.size,
        format: meta.format,
        storedAs,
        structureId: clean(form.structureId, 60),
        panelId: clean(form.panelId, 60),
        panelLabel: clean(form.panelLabel, 60),
        panelWidthMm: widthMm,
        panelHeightMm: heightMm,
        widthPx: meta.widthPx ?? undefined,
        heightPx: meta.heightPx ?? undefined,
        colour: meta.colour,
        effectiveDpi: report.effectiveDpi ?? undefined,
        errors: summary.errors,
        warnings: summary.warnings,
        ready: report.ready,
        findings: JSON.stringify(report.findings),
        meta: JSON.stringify(meta),
      },
    })
  } catch (error) {
    console.error('[artwork] create failed', error)
    return c.json({ error: 'The check ran but could not be recorded. Please try again.' }, 500)
  }

  return c.json({ ok: true, id: artworkReference, reference: artworkReference, meta, report: { ...report, summary } }, 201)
})

/** The file itself, for the proof view and for the person at press. */
app.get('/artwork/:id/file', async (c) => {
  if (!adminToken(c)) return c.json(UNAUTHORISED, 401)
  const id = c.req.param('id')
  const row = await prisma.artwork.findFirst({ where: { OR: [{ id }, { reference: id }] } })
  if (!row) return c.json({ error: 'No artwork with that reference.' }, 404)

  const full = path.join(process.cwd(), '.data', 'artwork', row.storedAs)
  // `storedAs` is written by the upload route, but a row is data like any other:
  // refuse to read anything whose resolved path leaves the artwork directory.
  const artworkDir = path.resolve(process.cwd(), '.data', 'artwork')
  if (!path.resolve(full).startsWith(artworkDir + path.sep)) {
    return c.json({ error: 'That artwork reference has no readable file.' }, 404)
  }
  try {
    const buf = await readFile(full)
    return c.body(new Uint8Array(buf), 200, {
      'content-type': row.mime,
      'content-disposition': `inline; filename="${encodeURIComponent(row.filename)}"`,
      'cache-control': 'private, max-age=300',
      // Uploaded bytes are served from the app's own origin: never let the
      // browser re-interpret them as HTML or SVG.
      'x-content-type-options': 'nosniff',
      'content-security-policy': "default-src 'none'; sandbox",
    })
  } catch {
    return c.json({ error: 'The stored file is missing for that artwork reference.' }, 410)
  }
})

