/**
 * Enquiries contain customer names, phone numbers and their artwork, so the
 * inbox is gated server-side. The passcode lives in `ADMIN_PASSCODE` — never in
 * the bundle. Tokens are random, held in process memory and expire; a restart
 * simply signs everyone out rather than leaving a stale credential usable.
 */
const ADMIN_TTL_MS = 8 * 60 * 60 * 1000
const adminSessions = new Map<string, number>()
const adminAttempts = new Map<string, number[]>()

function constantTimeEqual(a: string, b: string): boolean {
  const left = Buffer.from(a)
  const right = Buffer.from(b)
  if (left.length !== right.length) {
    // Still compare something of equal length so the failure costs the same.
    timingSafeEqual(left, left)
    return false
  }
  return timingSafeEqual(left, right)
}

function adminToken(c: { req: { header: (n: string) => string | undefined } }): string | null {
  const header = c.req.header('authorization') ?? ''
  const token = header.toLowerCase().startsWith('bearer ') ? header.slice(7).trim() : ''
  if (!token) return null
  const expiry = adminSessions.get(token)
  if (!expiry) return null
  if (expiry < Date.now()) {
    adminSessions.delete(token)
    return null
  }
  return token
}

const UNAUTHORISED = { error: 'Sign in with the business passcode to open enquiries.' }

app.get('/admin/status', (c) => {
  const configured = Boolean(process.env.ADMIN_PASSCODE?.trim())
  return c.json({ configured })
})

app.post('/admin/session', async (c) => {
  const expected = process.env.ADMIN_PASSCODE?.trim() ?? ''
  if (!expected) {
    return c.json(
      { error: 'No business passcode is configured on the server. Set ADMIN_PASSCODE in .env and restart.' },
      412,
    )
  }

  const ip = c.req.header('x-forwarded-for')?.split(',')[0]?.trim() || 'local'
  const now = Date.now()
  const recent = (adminAttempts.get(ip) ?? []).filter((t) => now - t < 60_000)
  if (recent.length >= 8) {
    return c.json({ error: 'Too many attempts. Wait a minute and try again.' }, 429)
  }
  recent.push(now)
  adminAttempts.set(ip, recent)

  let body: Record<string, unknown> = {}
  try {
    body = (await c.req.json()) as Record<string, unknown>
  } catch {
    return c.json({ error: 'Send the passcode as JSON.' }, 400)
  }

  if (!constantTimeEqual(String(body.passcode ?? ''), expected)) {
    return c.json({ error: 'That passcode is not right.' }, 401)
  }

  const token = randomBytes(24).toString('hex')
  adminSessions.set(token, now + ADMIN_TTL_MS)
  return c.json({ token, expiresAt: new Date(now + ADMIN_TTL_MS).toISOString() })
})

app.post('/admin/signout', (c) => {
  const token = adminToken(c)
  if (token) adminSessions.delete(token)
  return c.json({ ok: true })
})

app.get('/admin/enquiries', async (c) => {
  if (!adminToken(c)) return c.json(UNAUTHORISED, 401)

  const [leads, artworks] = await Promise.all([
    prisma.lead.findMany({ orderBy: { createdAt: 'desc' }, take: 200 }),
    prisma.artwork.findMany({ orderBy: { createdAt: 'desc' }, take: 500 }),
  ])

  const byLead = new Map<string, typeof artworks>()
  for (const art of artworks) {
    if (!art.leadId) continue
    const list = byLead.get(art.leadId) ?? []
    list.push(art)
    byLead.set(art.leadId, list)
  }

  return c.json({
    total: leads.length,
    enquiries: leads.map((lead) => ({
      id: lead.id,
      reference: lead.reference,
      kind: lead.kind,
      status: lead.status,
      createdAt: lead.createdAt,
      name: lead.name,
      company: lead.company,
      email: lead.email,
      phone: lead.phone,
      quantity: lead.quantity,
      pincode: lead.pincode,
      postalCode: lead.postalCode ?? lead.pincode,
      country: lead.country,
      countryName: lead.countryName,
      currency: lead.currency,
      fx: lead.baseAmount == null
        ? null
        : {
            baseCurrency: lead.baseCurrency,
            baseAmount: lead.baseAmount,
            rate: lead.fxRate,
            displayAmount: lead.displayAmount,
            fetchedAt: lead.fxFetchedAt,
          },
      destination: lead.destination,
      productSlug: lead.productSlug,
      structureId: lead.structureId,
      dimensions: lead.dimensions,
      board: lead.board,
      finishing: lead.finishing,
      foil: lead.foil,
      printing: lead.printing,
      deliveryRequirements: lead.deliveryRequirements,
      message: lead.message,
      payload: lead.payload ? safeJson(lead.payload) : null,
      source: lead.source,
      artworks: (byLead.get(lead.id) ?? []).map((art) => ({
        reference: art.reference,
        filename: art.filename,
        format: art.format,
        bytes: art.bytes,
        ready: art.ready,
        errors: art.errors,
        warnings: art.warnings,
        effectiveDpi: art.effectiveDpi,
        colour: art.colour,
        panel: art.panelLabel,
        panelWidthMm: art.panelWidthMm,
        panelHeightMm: art.panelHeightMm,
        findings: art.findings ? safeJson(art.findings) : [],
        url: `/api/artwork/${art.reference}/file`,
      })),
    })),
  })
})

