app.post('/admin/market/rates/manual', async (c) => {
  if (!adminToken(c)) return c.json({ error: 'Sign in with the business passcode.' }, 401)
  let body: Record<string, unknown> = {}
  try {
    body = (await c.req.json()) as Record<string, unknown>
  } catch {
    return c.json({ error: 'Send JSON.' }, 400)
  }
  const quote = String(body.currency ?? '').trim().toUpperCase()
  const rate = Number(body.rate)
  if (!isCurrencyCode(quote)) return c.json({ error: 'Choose a supported currency.' }, 400)
  if (!Number.isFinite(rate) || rate <= 0) {
    return c.json({ error: 'A rate must be a positive number.' }, 400)
  }
  const policy = await loadPolicy()
  if (quote === policy.fx.baseCurrency) {
    return c.json({ error: `The base currency (${quote}) always converts at 1.` }, 400)
  }
  const recorded = await recordManualRate(quote, rate, policy.fx.baseCurrency)
  return c.json({ ok: true, rate: recorded })
})

